import{_ as t,C as s,o as a,c as r,j as e,a as n,E as l,a5 as i}from"./chunks/framework.DjDdFq93.js";const y=JSON.parse('{"title":"说实话","description":"","frontmatter":{"title":"说实话","prev":{"text":"作品目录","link":"/books/honestly/"},"next":{"text":"返回作品目录","link":"/books/honestly/"}},"headers":[],"relativePath":"books/honestly/01.md","filePath":"books/honestly/01.md"}'),d={name:"books/honestly/01.md"};function _(c,p,h,k,m,b){const o=s("ReadingTools");return a(),r("div",null,[p[0]||(p[0]=e("h1",{id:"说实话",tabindex:"-1"},[n("说实话 "),e("a",{class:"header-anchor",href:"#说实话","aria-label":'Permalink to "说实话"'},"​")],-1)),p[1]||(p[1]=e("p",{class:"book-author"},"Honestly · Deidra Whitt Lovegren · 中文译文",-1)),l(o,{id:"honestly/01",markable:""}),p[2]||(p[2]=i('<div class="chapter-body"><p>“我曾经爱过的女人啊，咱们今晚吃点什么？”</p><p>“说实话，我这辈子最大的失望啊？随便。”</p><p>“你才在乎呢。你是想让我提个地方，然后你把它一口否决掉。不管我说什么，你都会皱着那小鼻子，好像我提议咱们吃猫砂盆里的东西似的。”</p><p>“你错得不能再错了，不过你一向如此。”</p><p>“你下班路上能不能顺便带点外卖回来。”</p><p>“我能，但我不会。咱们每晚关于晚饭的对话，是我们一天中唯一真实的交流，所以我要尽量把它拖得越长越好。这是我唯一能用最拐弯抹角的敌意来控制你的办法，因为我知道你此刻又饿又暴躁。”</p><p>“全对。嘿，我要点泰式炒河粉。不是说你会对什么都满意，但你一般不会讨厌那个。我不会点春卷，因为你喜欢。相反，我会点我喜欢的脆皮那种——就是故意气你。等你抱怨的时候，我就反驳说下次该你去买晚饭。然后你就会躲进卧室生气，我就能安安静静看电视，不用在精彩的地方被你打扰。”</p><p>“唉，我其实不太想吃泰国菜。”</p><p>“当然不想。那你想吃什么？”</p><p>“我想要你像我们恋爱时那样对我。”</p><p>“我想要你看起来像我们恋爱时那样。塔可钟怎么样？”</p><p>“能不能找个不用纸餐巾、也没有大肠杆菌爆发纪录的地方？”</p><p>“一个周三你想讲究到什么程度？你为什么每顿饭都纠结得像那是你人生最后一餐一样？这不过是食物，又不是承诺——不像你当年把我哄进去的那个。你当时其实没真怀孕，对吧？”</p><p>“当然没有。但我以为我可能怀了。”</p><p>“啊，是啊。咱们从没真正谈过你那时候的不诚实，不过咱们就把它扫到地毯底下，再放个几年不去管，直到被逼着去做婚姻咨询。”</p><p>“同意。但今晚，我想坐下来，照着菜单点餐。我不想要外带、免下车、快捷休闲餐，也不想抽号排队，更不想吃7-11的微波墨西哥卷。咱们去一家有真正男女服务员的餐厅吧。你还记得女服务员是什么样吗？我记得你上一次出轨，就是跟你公司附近那家餐馆的金发女服务员。”</p><p>“那根本算不上出轨。顶多是两个月的短暂恋情。她秋天就回大学去了。那咱们干脆把正式餐厅留给特殊场合吧？比如周末？我小时候可不记得天天在外面吃。我妈一天做三顿饭！”</p><p>“你妈不用上班。要是咱们负担得起，我也想待在家里，煮一盒 Rice-A-Roni 速食饭，把猪排煮过头，再端上一盘童年阴影——跟你妈一样。”</p><p>“你一点都不像我妈。有时候我真希望自己能凑出足够的情绪来恨你。可现实是，你只是个烦人的存在。房间里的一只蚊子。肥皂上的一根毛发。鞋底的口香糖。”</p><p>“Applebee&#39;s。”</p><p>“Applebee&#39;s？”</p><p>“或者别的什么中等价位的家庭餐厅。随便挑一个。德州牛排馆。橄榄园。澳美客牛排馆。”</p><p>“完美。咱们去一家全服务的餐厅，花7.99美元买一个熔岩巧克力蛋糕，你咬一口就不吃了。然后你就能舒舒服服地坐着，让一群比你年轻一半的女孩跑来跑去，给你端来你想要的所有健怡可乐——再加一盘青柠！整个19世纪，英国海军消耗的青柠都没你一个人多。”</p><p>“我。等。不。了。咱们去一家你会拒绝前三次安排座位的餐厅，让我在服务员面前丢尽脸面。你到底跟坐卡座有什么过不去的？你会问服务员生啤有什么款，然后不管答案都点米勒淡啤，还会把整个面包篮吃光。看菜单十秒钟之后，你就会点最不健康的东西——塞满馅的、裹面糊的、抹黄油的、炸的、奶油浓郁的、挂糖浆的、超大份的，或者裹着巧克力的。而且，对，你当然还要配薯条。双份！”</p><p>“那你呢……花十五分钟研究菜单，就跟一个埃及学家第一次见到罗塞塔石碑似的，然后你会点你永远点的那个：烤鸡胸肉。花17.99美元买一块你在家微波就能搞定的淡而无味的冻鸡肉。”</p><p>“你想让我在家做饭？用咱家那些老古董电器，哪怕是戈登·拉姆齐都整不出一份烤面包配豆子来。”</p><p>“又来了。”</p><p>“你当年答应我，等孩子大了咱们就搬进更大的房子。好吧，他们长大了，上大学走了。现在就只剩你跟我，还住在这同一个两千平方英尺的破棚子里。”</p><p>“那个破棚子都快还完贷款了。我烦透了看房子。没必要搬。你为什么非要让咱们的房贷翻倍？别再看HGTV了。要是你运气好，说不定乔安娜和奇普·盖恩斯会把咱家破棚子拿去上《房屋翻新秀》。”</p><p>“你要是有奇普·盖恩斯一半像个男人就好了。”</p><p>“要是你有乔安娜一半的好看就好了。”</p><p>“你从来不肯动一动手指帮忙做家务。”</p><p>“自从孩子们上大学走了，你连一个锅都没碰过。要那些家电有什么用，要是你根本不用它们？”</p><p>“跟你办健身房会员卡的理由一样。”</p><p>“哦我的上帝，我才不要坐在任何一家餐厅的餐桌对面——或者卡座里都不行——盯着你的脸看四十五分钟。我不想听你抱怨公司谁没把复印机的卡纸弄出来。我也不想听你爹最近去医院看病，哪里又切开排脓了。我现在唯一能承受的，就是决定咱们要吃什么。我会买下来，看着你把它塞进肚子里，然后暗自庆幸自己今晚没有把车装满东西离开你。”</p><p>“哦，求你今晚就走吧。我会帮你打包的。我会尽量不去怀念那些漫漫长夜，你跟狗说话都比跟我说得多，那些你总也塞不进洗衣篮的衣服，还有你随手扔在屋子各处等洗碗仙女来收的六个杯子。”</p><p>“那，披萨？”</p><p>“披萨总不会错。”</p><p>🜋 🜋 🜋</p><p>“亲爱的，咱们今晚吃点什么？”</p><p>“说实话，宝贝？随便。”</p><p>“那，披萨？”</p><p>“披萨总不会错。”</p></div><hr><p><a href="https://reedsy.com/short-story/ymkv0n/" target="_blank" rel="noreferrer">原文入口</a> · <a href="/books/honestly/">返回作品目录</a></p>',3))])}const T=t(d,[["render",_]]);export{y as __pageData,T as default};
